import sqlite3


def get_connection():
    return sqlite3.connect("shop.db")


def run_query(sql, params=None):
    conn = get_connection()
    cursor = conn.cursor()
    cursor.execute(sql, params or ())
    rows = cursor.fetchall()
    conn.close()
    return rows

